// src/App.js
import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Route, Routes, Navigate } from 'react-router-dom';
import axios from 'axios';

// Components
import Login from './components/Login';
import Dashboard from './components/Dashboard';
import PatientForm from './components/PatientForm';
import TriageResult from './components/TriageResult';
import PatientQueue from './components/PatientQueue';
import Header from './components/Header';
import Sidebar from './components/Sidebar';
import ProtectedRoute from './components/ProtectedRoute';

// Styles
import './App.css';

// API Configuration
const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:8000';

function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [user, setUser] = useState(null);
  const [token, setToken] = useState(localStorage.getItem('token') || null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  
  // Check if user is authenticated on initial load
  useEffect(() => {
    const checkAuth = async () => {
      if (token) {
        try {
          const response = await axios.get(`${API_URL}/users/me`, {
            headers: { Authorization: `Bearer ${token}` }
          });
          
          setUser(response.data);
          setIsAuthenticated(true);
        } catch (err) {
          console.error('Authentication error:', err);
          localStorage.removeItem('token');
          setToken(null);
          setIsAuthenticated(false);
        }
      }
      setLoading(false);
    };
    
    checkAuth();
  }, [token]);
  
  // Login handler
  const handleLogin = async (credentials) => {
    try {
      setLoading(true);
      
      // Prepare form data
      const formData = new FormData();
      formData.append('username', credentials.username);
      formData.append('password', credentials.password);
      
      const response = await axios.post(`${API_URL}/token`, formData);
      
      const { access_token } = response.data;
      
      // Save token to localStorage
      localStorage.setItem('token', access_token);
      setToken(access_token);
      
      // Get user info
      const userResponse = await axios.get(`${API_URL}/users/me`, {
        headers: { Authorization: `Bearer ${access_token}` }
      });
      
      setUser(userResponse.data);
      setIsAuthenticated(true);
      setError(null);
      
    } catch (err) {
      console.error('Login error:', err);
      setError('Invalid username or password');
    } finally {
      setLoading(false);
    }
  };
  
  // Logout handler
  const handleLogout = () => {
    localStorage.removeItem('token');
    setToken(null);
    setUser(null);
    setIsAuthenticated(false);
  };
  
  if (loading) {
    return <div className="loading">Loading...</div>;
  }
  
  return (
    <Router>
      <div className="app">
        {isAuthenticated && <Header user={user} onLogout={handleLogout} />}
        <div className="app-container">
          {/* Welcome message moved above sidebar */}
          {isAuthenticated && (
            <div className="welcome-banner">
              <h2>Welcome, {user?.username === 'doctor' ? 'ER Doctor' : 'ER Nurse'}</h2>
              <span className="user-role">{user?.username === 'doctor' ? 'Doctor' : 'Nurse'}</span>
              <button onClick={handleLogout} className="logout-button">Logout</button>
            </div>
          )}
          
          {isAuthenticated && <Sidebar />}
          <main className="main-content">
            <Routes>
              <Route 
                path="/login" 
                element={!isAuthenticated ? (
                  <Login onLogin={handleLogin} error={error} />
                ) : (
                  <Navigate to="/dashboard" replace />
                )} 
              />
              <Route 
                path="/dashboard" 
                element={
                  <ProtectedRoute isAuthenticated={isAuthenticated}>
                    <Dashboard user={user} />
                  </ProtectedRoute>
                } 
              />
              <Route 
                path="/patient/new" 
                element={
                  <ProtectedRoute isAuthenticated={isAuthenticated}>
                    <PatientForm token={token} apiUrl={API_URL} />
                  </ProtectedRoute>
                } 
              />
              <Route 
                path="/triage/:patientId" 
                element={
                  <ProtectedRoute isAuthenticated={isAuthenticated}>
                    <TriageResult token={token} apiUrl={API_URL} />
                  </ProtectedRoute>
                } 
              />
              <Route 
                path="/queue" 
                element={
                  <ProtectedRoute isAuthenticated={isAuthenticated}>
                    <PatientQueue token={token} apiUrl={API_URL} />
                  </ProtectedRoute>
                } 
              />
              <Route path="/" element={<Navigate to={isAuthenticated ? "/dashboard" : "/login"} replace />} />
            </Routes>
          </main>
        </div>
      </div>
    </Router>
  );
}

export default App;
